; FX module: the shared effects library (docs/agents/snes-port/fx.md).
; Renders native spell cells, beams, auras, lightning, explosions and screen
; flashes for combat, flight and the scene modules; never decides gameplay.
;
; Resources:
;   code  $AE:8000-FFFF (!CODE_FX, upper half only)
;   data  !FX_DATA (= !DATA_FX, one bank): assemblies, palettes and CPU tables
;   xdata cell tiles and bulk geometry, generated by snes/gen/fx.mjs
;   SRAM  $31:7800-7BFF (!SRAM_WORK_FX)
;   VRAM  core regions FIELD_OBJ_A/B/C while effects are active (owner $0E)
;   CGRAM free OBJ palettes per frame, written in vblank after the game's
;   DMA   channel 7 (6 when 7 runs HDMA) inside fx_nmi
;   stack fx_frame keeps a 144-byte direct-page frame on the stack (S is
;         about $01EC there, so the frame ends near $015C)
;
; Calling convention: JSL, M16/X16, DB = $7E, D = 0 on entry and exit;
; DB and D preserved, A/X/Y clobbered unless noted. asar does not track
; REP/SEP: every immediate carries .b or .w.

incsrc "defs.asm"
assert !FX_SRAM == !SRAM_WORK_FX, "fx request block must sit at !SRAM_WORK_FX"

; Public, defined by the library itself (not by defs.asm): draw-list entries
; per frame, shared by fx_draw and fx_beam. Modules included after FX
; (modules.asm) can test `if defined("FX_DRAWS")` for the real library.
!FX_DRAWS     = 8

; ---------------------------------------------------------------------------
; Private state (SRAM, long addressing). Contents are undefined at power-on:
; fx_ensure_init clears everything when the magic word is missing.
!fx_tick      = !FX_SRAM+$10   ; word: core tick the draw list belongs to
!fx_camx      = !FX_SRAM+$12   ; word: camera (map pixel at screen 0,0)
!fx_camy      = !FX_SRAM+$14   ; word
!fx_map       = !FX_SRAM+$16   ; word: map id of the last fx frame
!fx_mode      = !FX_SRAM+$18   ; word: core mode of the last fx frame
!fx_gen       = !FX_SRAM+$1A   ; word: last handle generation (1-255)
!fx_ndraw     = !FX_SRAM+$1C   ; word: draw-list bytes used
!fx_idle      = !FX_SRAM+$1E   ; word: consecutive frames without effects
!fx_palfree   = !FX_SRAM+$20   ; low byte: free OBJ palettes; bit 8: a palette acquired
!fx_clspal    = !FX_SRAM+$22   ; 7 bytes: OBJ palette per class this frame ($FF none)
!fx_nmipal    = !FX_SRAM+$29   ; 7 bytes: copy handed to fx_nmi
!fx_regions   = !FX_SRAM+$30   ; word: claimed VRAM regions (bit0 A, bit1 B, bit2 C)
!fx_flash     = !FX_SRAM+$32   ; word: flash frames left
!fx_flashamt  = !FX_SRAM+$34   ; word: flash amount for the next vblank (0 none)
!fx_mathon    = !FX_SRAM+$36   ; word: colour math currently overridden by FX
!fx_quake     = !FX_SRAM+$38   ; word: quake frames left
!fx_quakeprev = !FX_SRAM+$3A   ; word: $49 before the pulse
!fx_bmiss     = !FX_SRAM+$3C   ; word: a cell missed this frame's upload budget (fx_cache_get)
!fx_pbig      = !FX_SRAM+$3E   ; word: polygon tables in both buffers: bit 0 this frame's request,
                               ;   bit 1 on screen, bit 2 the ones the key describes
!fx_ccell     = !FX_SRAM+$40   ; 16 words: VRAM cache entry -> cell ($FFFF free, $FFFE unusable)
!fx_cused     = !FX_SRAM+$60   ; 16 words: fx frame of last use
!fx_cpend     = !FX_SRAM+$80   ; word: entries to upload in the next vblank (bit per entry)
!fx_cbudget   = !FX_SRAM+$82   ; word: new cells still allowed this frame
!fx_frame     = !FX_SRAM+$84   ; word: fx frame counter
!fx_dyn       = !FX_SRAM+$86   ; 3 words: DYN colours for this frame's vblank
!fx_magic     = !FX_SRAM+$8C   ; word: !FX_MAGIC once initialised
!fx_poly_req  = !FX_SRAM+$8E   ; word: polygon requested this frame (0 none)
!fx_poly_on   = !FX_SRAM+$90   ; word: polygon programmed in the last vblank
!fx_sprites   = !FX_SRAM+$92   ; word: sprites emitted this frame (FX_TEST)
!fx_dropped   = !FX_SRAM+$94   ; word: parts skipped this frame (FX_TEST)
!fx_front     = !FX_SRAM+$96   ; word: front sprites FX used this frame
!fx_nlive     = !FX_SRAM+$98   ; word: spawned effects alive
!fx_hiwater   = !FX_SRAM+$9A   ; word: 16 * (highest slot used + 1) since the slots were last empty
!fx_busy      = !FX_SRAM+$9C   ; word: nonzero while FX holds anything (regions, flash, quake, polygon, uploads)
!fx_tight     = !FX_SRAM+$9E   ; word: the coming vblank has no time and HDMA runs: no FX sprites
!FX_MAGIC     = $F0C7
!fx_s         = !FX_SRAM+$A0   ; 16 bytes scratch for the API entry points
!fx_dual_cur  = !fx_s+$0C      ; draw-list offset while fx_run_draws runs
!fx_dual_pair = !fx_s+$0E      ; second draw consumed by the paired polygon
!fx_e         = !FX_SRAM+$B0   ; 16 bytes scratch for the cache
; Spawned effects: 14 slots of 16 bytes
!FX_SLOTS     = 14
!fx_slots     = !FX_SRAM+$C0
!S_KIND = $0   ; byte: kind, 0 = free
!S_FLAGS = $1  ; byte
!S_X = $2      ; word
!S_Y = $4      ; word
!S_AGE = $6    ; word: $FFFF until the first fx frame
!S_LIFE = $8   ; byte: frames shown (ages 0..life-1)
!S_HOLD = $9   ; byte: frames to freeze the age (impact contact hold)
!S_A = $A      ; word
!S_B = $C      ; word
!S_DIR = $E    ; byte
!S_GEN = $F    ; byte
; Draw list: !FX_DRAWS entries of 16 bytes, rebuilt every frame
!fx_draws     = !FX_SRAM+$1A0
!D_KIND = $0   ; byte (beams: $80 | style)
!D_FLAGS = $1
!D_X = $2
!D_Y = $4
!D_DIR = $6
!D_STYLE = $7
!D_A = $8
!D_B = $A
!D_C = $C
!D_T = $E
!fx_vbl       = !FX_SRAM+$220  ; word: vblank lines left when fx_nmi started (last frame)
!fx_dseq      = !FX_SRAM+$222  ; word: destroy's effect record last drawn (its FX_SEQ)
!fx_dshade    = !FX_SRAM+$224  ; word: map whose room shades !fx_dyn holds ($FFFF none)
!fx_phase     = !FX_SRAM+$226  ; word: the game's streaming phase ($56) for the coming vblank
!fx_cfail     = !FX_SRAM+$228  ; word: cache entries whose upload slipped (not drawn until done)
!fx_nmiwork   = !FX_SRAM+$22A  ; word: nonzero when the coming vblank has FX work
!fx_vblp      = !FX_SRAM+$22C  ; 5 words: learned vblank lines left for FX, per phase
; Polygon (HDMA) state, written by fx_frame, read by the next fx_nmi
!fx_pbuf      = !FX_SRAM+$236  ; word: back buffer for the next build (0 or !FX_PBUF_SIZE)
!fx_pdmap     = !FX_SRAM+$238  ; word: channel 2 DMAP (1: W1 only, 4: W1 and W2)
!fx_ptab2     = !FX_SRAM+$23A  ; word: channel 2 table (window edges)
!fx_ptab3     = !FX_SRAM+$23C  ; word: channel 3 table (backdrop colour)
!fx_pfix      = !FX_SRAM+$23E  ; 3 bytes: COLDATA writes (core = backdrop + fixed colour)
!fx_hash      = !FX_SRAM+$242  ; 16 bytes: cache entry*2 for cell & 15 (a stale value costs a scan)
!fx_pkey      = !FX_SRAM+$252  ; 6 words: parameters of the last built polygon (+8 = $FFFF: none)
!fx_pshown    = !FX_SRAM+$25E  ; word: that polygon is in the buffer on screen
!fx_preuse    = !FX_SRAM+$260  ; word: this frame shows it again (no build, no buffer swap)
!fx_rbits     = !FX_SRAM+$262  ; 48 bytes: bit per cell id resident in the cache
!FX_RBITS_SIZE = 48
!fx_poly      = !FX_SRAM+$292  ; two HDMA table buffers
!FX_PBUF_SIZE = ($400-$292)/2
assert !fx_draws+(!FX_DRAWS*16) <= !fx_vbl, "fx SRAM layout overlap"
assert !fx_slots+(!FX_SLOTS*16) <= !fx_draws, "fx SRAM layout overlap"
assert !fx_pfix+3 <= !fx_hash, "fx SRAM layout overlap"
assert !fx_preuse+2 <= !fx_rbits, "fx SRAM layout overlap"
assert !fx_rbits+!FX_RBITS_SIZE <= !fx_poly, "fx SRAM layout overlap"

; ---------------------------------------------------------------------------
; Direct-page frame: fx_frame moves S down !FXF_SIZE bytes and points D at
; the frame, so the renderers' locals are fast direct-page variables. Only
; code running inside fx_frame may use these; the game's own direct-page
; variables are then reached with explicit absolute addressing ($7E:00xx).
!FXF_SIZE = $94
!d_ax    = $00    ; word: anchor x - 128 + 15 (assembly part placement)
!d_ay    = $02
!d_n     = $04    ; word: parts left in the assembly
!d_sx    = $06    ; word: screen x of the part
!d_sy    = $08
!d_tile  = $0A    ; word
!d_end   = $0C    ; word: first OAM cursor value without room
!d_ptr   = $0E    ; 3 bytes: long pointer to the assembly (+3 parts)
!d_ptr2  = $11    ; 3 bytes: the same + 2 (third byte of each part)
!d_x     = $14    ; word: anchor (screen) for the next assembly
!d_y     = $16
!d_cur   = $18    ; 16 bytes: the effect being drawn (C_* offsets)
!d_ks     = $28    ; 16 bytes: kind scratch
!d_dx    = $38    ; word: direction registers (-1/0/1)
!d_dy    = $3A
!d_turn  = $3C    ; word: quarter turn 0-3
!d_ef    = $3E    ; word: emit flags (bit0 front)
!d_lastc = $40    ; word: last resolved cell word ($FFFF none)
!d_lasto = $42    ; word: its OAM word ($FFFF unavailable)
!d_size  = $44    ; word: high-table bits for a cell: 0 field, 2 world (large)
!d_white = $46    ; word: nonzero: all-white palette
!d_nc    = $48    ; word: cells left to resolve
!d_tmp   = $4A    ; 8 bytes
!d_k     = $52    ; word: fast placement offset ((y-128) << 8) + (x-128)
!d_tiles = $54    ; 24 words: per cell (6) the OAM word plain, h, v, hv ($FFFF missing)
!d_np    = $84    ; word: parts in the set-up assembly
!d_pofs  = $86    ; word: offset of its first part in fx_asm_data
!d_r0    = $88    ; 8 bytes: fx_emit_run state
!d_lasta = $90    ; word: assembly whose cells !d_tiles holds ($FFFF none)
!d_rstep = $92    ; word: fx_emit_run spacing in pixels
; Current effect fields (offsets into !d_cur)
!C_KIND = $0   ; byte (beams: $80 | style)
!C_FLAGS = $1  ; byte
!C_X = $2      ; word: screen x
!C_Y = $4      ; word: screen y
!C_DIR = $6    ; byte
!C_STYLE = $7  ; byte
!C_A = $8      ; word
!C_B = $A      ; word
!C_C = $C      ; word
!C_T = $E      ; word: age (slots) or client clock (draws)

; Emit flags (!d_ef)
!FX_E_FRONT = $0001
!FX_FRONT_MAX = 12          ; of the core's 16 front slots

; Call a core / other-module routine from inside the frame (they expect D=0).
macro fx_far(target)
	PHD
	PEA $0000
	PLD
	JSL <target>
	PLD
endmacro

; Assemblies and palettes in !DATA_FX; DMA-only cells in two xdata blobs.
; snes/test/fx/run.mjs verifies both blobs against the generated bytes.
if defined("DATA_FX")
	!FX_DATA = !DATA_FX
else
	!FX_DATA = $FB0000
endif
pushpc
org !FX_DATA
fx_cells = !XDATA_FX_CELLS_LO
fx_cells_hi = !XDATA_FX_CELLS_HI
fx_data:
incsrc "fx/data.asm"
; DMA source pointer per cell. Four bytes make indexing one shift pair;
; no bank selection, source multiplication or SRAM scratch in vblank.
fx_cell_dma:
for fxc = 0..!FX_CELL_COUNT
	if !fxc < 256
		dw (fx_cells+(!fxc*128))&$FFFF
		db fx_cells>>16, 0
	else
		dw (fx_cells_hi+((!fxc-256)*128))&$FFFF
		db fx_cells_hi>>16, 0
	endif
endfor
fx_data_end:
assert fx_data_end <= !FX_DATA+$10000, "fx data overflows its bank"
assert !FX_CELL_COUNT <= !FX_RBITS_SIZE*8, "fx residency bitmap too small for the cells"
pullpc

if defined("FX_TEST")
!FXT_BOX = $326000                 ; test mailbox (snes/test/fx/testmod.asm)
!fx_vbl_end   = !FXT_BOX+$C4       ; lines left after FX's vblank work (last frame)
!fx_upl       = !FXT_BOX+$C6       ; cells uploaded in the last vblank
endif

; destroy's effect record (docs/agents/snes-port/destroy.md, "Outputs";
; SRAM !SRAM_WORK_DESTROY+$7F8): FX draws each new record.
!FX_DREC      = !SRAM_WORK_DESTROY+$7F8
!FX_DREC_SEQ  = !FX_DREC+0         ; word, increments per record
!FX_DREC_KIND = !FX_DREC+2         ; 1 rubble burst, 2 brazier burst
!FX_DREC_X    = !FX_DREC+4         ; map pixels
!FX_DREC_Y    = !FX_DREC+6

pushpc
org !CODE_FX
fx_code_start:
incsrc "api.asm"
incsrc "frame.asm"
incsrc "emit.asm"
incsrc "kinds.asm"
incsrc "poly.asm"
incsrc "red.asm"
incsrc "clash.asm"
incsrc "nmi.asm"
if defined("FX_TEST")
	incsrc "../../../test/fx/testmod.asm"
endif
fx_tables:
incsrc "fx/tables.asm"             ; generated tables read with long loads
fx_code_end:
assert fx_code_end <= !CODE_FX+$8000, "fx code bank overflow"
pullpc
